const decodeConversationPage = Schema.decodeUnknownSync(OpenbotConversationPage);

function useRetainedBotNavigation() {
  const location = useLocation();
  const [retained, setRetained] = useState(location.search);
  const onBots = location.pathname === "/bots" || location.pathname === "/bots/";
  if (onBots && retained !== location.search) setRetained(location.search);
  return validateBotWorkspaceSearch(onBots ? location.search : retained);
}

/** React composition of the upstream sidebar + conversation + tools layout. */
export function ReactBotWorkspace({ active }: { active: boolean }) {
  const { environments } = useSettingsScope();
  const navigate = useNavigate();
  const requestedMachine = useRetainedBotNavigation().machine;
  const [selected, setSelected] = useState<EnvironmentId | null>(null);
  const environment = selectWorkspaceEnvironment(
    environments,
    environments.find((item) => item.environmentId === requestedMachine)?.environmentId ?? selected,
  );
  return (
    <div className="flex min-h-0 flex-1 flex-col">
      {environments.length > 1 && (
        <div className="flex flex-wrap items-center gap-3 border-b border-border/60 px-4 py-2">
          <span className="text-xs text-muted-foreground">Computer</span>
          <div className="w-60 max-w-full">
            <Select
              value={environment?.environmentId ?? ""}
              items={environments.map((item) => ({ value: item.environmentId, label: item.label }))}
              onValueChange={(value) => {
                const next = environments.find((item) => item.environmentId === value);
                if (!next) return;
                setSelected(next.environmentId);
                void navigate({
                  to: "/bots",
                  search: { machine: next.environmentId, botPage: "chats" },
                });
              }}
            >
              <SelectTrigger aria-label="Bots computer">
                <SelectValue />
              </SelectTrigger>
              <SelectPopup>
                {environments.map((item) => (
                  <SelectItem key={item.environmentId} value={item.environmentId}>
                    {item.label}
                  </SelectItem>
                ))}
              </SelectPopup>
            </Select>
          </div>
        </div>
      )}
      {environment ? (
        <EnvironmentWorkspace
          key={environment.environmentId}
          environmentId={environment.environmentId}
          label={environment.label}
          active={active}
        />
      ) : (
        <Empty size="compact">
          <EmptyHeader>
            <EmptyMedia>
              <BotIcon aria-hidden className="size-7" />
            </EmptyMedia>
            <EmptyTitle>Connect to your bots</EmptyTitle>
            <EmptyDescription>
              Choose a Sled computer to open its bots and conversations.
            </EmptyDescription>
          </EmptyHeader>
          <EmptyContent>
            <Button variant="outline" render={<Link to="/settings/connections" />}>
              Open connections
            </Button>
          </EmptyContent>
        </Empty>
      )}
    </div>
  );
}

function EnvironmentWorkspace({
  environmentId,
  label,
  active,
}: {
  environmentId: EnvironmentId;
  label: string;
  active: boolean;
}) {
  const host = useEnvironmentQuery(openbot.status({ environmentId, input: {} }));
  const agents = useEnvironmentQuery(
    host.data?.state === "ready" ? openbot.agents({ environmentId, input: {} }) : null,
  );
  const channels = useEnvironmentQuery(
    host.data?.state === "ready" && host.data.hostId
      ? openbot.readFromHost({
          environmentId,
          input: { hostId: host.data.hostId, request: { operation: "channel.list" } },
        })
      : null,
  );
  const agentDetails = useEnvironmentQuery(
    host.data?.state === "ready" && host.data.hostId
      ? openbot.readFromHost({
          environmentId,
          input: { hostId: host.data.hostId, request: { operation: "agent.list" } },
        })
      : null,
  );
  const [history, setHistory] = useState<{
    entries: { hostId: string; kind: "bot" | "group" | "person"; id: string }[];
    index: number;
  }>({ entries: [], index: -1 });
  const [selectedPerson, setSelectedPerson] = useState<{ hostId: string; id: string } | null>(null);
  const [selectedChannel, setSelectedChannel] = useState<string | null>(null);
  const [groupCreation, setGroupCreation] = useState<string | null>(null);
  const [selected, setSelected] = useState<{ hostId: string; agentId: string } | null>(() => {
    try {
      return readWorkspaceBot(environmentId, window.localStorage);
    } catch {
      return null;
    }
  });
  const [draftThreadScope, setDraftThreadScope] = useState<string | null>(null);
  const [sideThreadSelection, setSideThreadSelection] = useState<{
    scope: string;
    id: string;
  } | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const [focusMessageId, setFocusMessageId] = useState<string | undefined>(undefined);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [view, setSelectedView] = useState<BotWorkspaceView>("Chat");
  const [panelVisible, setPanelVisible] = useState(false);
  const [panes, setPanes] = useState<readonly SourcePane[]>(["Files"]);
  const [maximized, setMaximized] = useState(false);
  const setView = (next: BotWorkspaceView) => {
    if (next === "Settings") {
      void navigate({
        to: "/settings/bots",
        search: { machine: environmentId },
        hash: selected ? `bot-agent-${selected.agentId}` : "bot-host-agents",
      });
      return;
    }
    setSelectedView(next);
    setPanelVisible(next !== "Chat");
    if (next !== "Chat" && next !== "Tasks")
      setPanes((old) => (old.includes(next) ? old : [...old, next]));
  };
  const openProviders = () => {
    void navigate({
      to: "/settings/bots",
      search: { machine: environmentId },
      hash: "bot-host-providers",
    });
  };
  const [routineTarget, setRoutineTarget] = useState<{ agentId: string; id: string | null } | null>(
    null,
  );
  const navigate = useNavigate();
  const navigation = useRetainedBotNavigation();
  const [section, setSectionState] = useState<BotWorkspaceSection>("chats");
  const handledNavigation = useRef<string | null>(null);
  const setSection = (next: BotWorkspaceSection) => {
    if (next === "settings" || next === "host-settings") {
      void navigate({
        to: next === "settings" ? "/settings/general" : "/settings/bots",
        search: { machine: environmentId },
        ...(next === "host-settings" ? { hash: "bot-host-general" } : {}),
      });
    } else if (next === "usage") {
      void navigate({ to: "/usage", search: { view: "bots", machine: environmentId } });
    } else {
      setSectionState(next);
      const page = next === "groups" || next === "direct" ? "chats" : next;
      if (navigation.botPage !== page) {
        const search = { machine: environmentId, botPage: page, botVisit: randomUUID() };
        handledNavigation.current = JSON.stringify(validateBotWorkspaceSearch(search));
        void navigate({ to: "/bots", search });
      }
    }
  };
  const hostId = host.data?.state === "ready" ? (host.data.hostId ?? null) : null;
  const people = useBotPeople(environmentId, hostId);
  const person =
    selectedPerson?.hostId === hostId
      ? people.members.find((member) => member.id === selectedPerson.id && !member.disabled)
      : undefined;
  const bot =
    selected && selected.hostId === hostId
      ? agents.data?.find((item) => item.id === selected.agentId)
      : undefined;
  const tasks = useEnvironmentQuery(
    bot && hostId
      ? openbot.readFromHost({
          environmentId,
          input: { hostId, request: { operation: "task.list", agentId: bot.id } },
        })
      : null,
  );
  const threadScope = JSON.stringify([environmentId, hostId, bot?.id ?? null]);
  const [threadLayout, setThreadLayout] = useOpenbotThreadTabLayout(threadScope);
  const selectedTaskId = threadLayout.active;
  const newThread = draftThreadScope === threadScope;
  const selectedSideThread =
    sideThreadSelection?.scope === threadScope && threadLayout.side.includes(sideThreadSelection.id)
      ? sideThreadSelection.id
      : (threadLayout.side[0] ?? null);
  const selectThread = (id: string | null) => {
    setFocusMessageId(undefined);
    setDraftThreadScope(null);
    setThreadLayout({
      ...threadLayout,
      active: id,
      open: id && !threadLayout.open.includes(id) ? [...threadLayout.open, id] : threadLayout.open,
      side: id ? threadLayout.side.filter((other) => other !== id) : threadLayout.side,
    });
  };
  const moveThreadToSide = (id: string) => {
    setThreadLayout(dockThreadTab(threadLayout, id, "side"));
    setSideThreadSelection({ scope: threadScope, id });
    setView("Chat");
    setPanelVisible(true);
  };
  const renameThread = useAtomCommand(openbot.writeToHost, { reportFailure: false });
  const renameLock = useRef(false);
  const [threadError, setThreadError] = useState<string | null>(null);
  const draftKey = `${hostId}:${bot?.id}:${selectedTaskId ?? "main"}`;
  const [quotedFile, setQuotedFile] = useState<{
    key: string;
    preview: BotQuotedFilePreview;
  } | null>(null);
  const scope = bot && hostId ? { environmentId, hostId, agentId: bot.id } : null;
  const selectBot = (id: string) => {
    if (!hostId) return;
    setDraftThreadScope(null);
    setSelected({ hostId, agentId: id });
    try {
      retainWorkspaceBot(environmentId, { hostId, agentId: id }, window.localStorage);
    } catch {
      /* Selection survives when storage is unavailable. */
    }
  };
  const openChat = (kind: "bot" | "group" | "person", id: string, record = true) => {
    if (!hostId) return;
    setFocusMessageId(undefined);
    if (kind === "bot") {
      selectBot(id);
      setSection("chats");
      setView("Chat");
    } else if (kind === "person") {
      setSelectedPerson({ hostId, id });
      setSection("direct");
    } else {
      setGroupCreation(null);
      setSelectedChannel(id);
      setSection("groups");
    }
    if (record)
      setHistory((current) => {
        const entry = current.entries[current.index];
        if (entry?.hostId === hostId && entry.kind === kind && entry.id === id) return current;
        const entries = [...current.entries.slice(0, current.index + 1), { hostId, kind, id }];
        return { entries, index: entries.length - 1 };
      });
  };
  const openAgentThread = (agentId: string, taskId: string | null, messageId?: string) => {
    if (!hostId) return;
    const destination = JSON.stringify([environmentId, hostId, agentId]);
    let layout = {
      open: [] as readonly string[],
      side: [] as readonly string[],
      active: null as string | null,
    };
    try {
      layout = readThreadTabLayout(destination, window.localStorage) ?? layout;
    } catch {
      /* Storage is optional. */
    }
    openChat("bot", agentId);
    setThreadLayout(
      {
        ...layout,
        active: taskId,
        open: taskId && !layout.open.includes(taskId) ? [...layout.open, taskId] : layout.open,
        side: taskId ? layout.side.filter((id) => id !== taskId) : layout.side,
      },
      destination,
    );
    setFocusMessageId(messageId);
  };
  const readNavigation = useAtomQueryRunner(openbot.readFromHost, {
    reportFailure: false,
    refresh: true,
  });
  const getNavigationScope = useStableCallback(() => threadScope);
  const openFileConversation = async (conversationId: string, messageId?: string) => {
    if (!scope) return;
    const captured = threadScope,
      connection = readPreparedConnection(environmentId);
    const settled = await settlePromise(async () => {
      const result = await readNavigation({
        environmentId,
        input: {
          hostId: scope.hostId,
          request: {
            operation: "conversation.page",
            agentId: scope.agentId,
            anchor: { type: "latest" },
            limit: 1,
          },
        },
      });
      if (getNavigationScope() !== captured || readPreparedConnection(environmentId) !== connection)
        return;
      if (result._tag === "Failure") throw Error("Conversation lookup failed.");
      const page = decodeConversationPage(result.value);
      if (page.agentId !== scope.agentId) throw Error("Conversation owner changed.");
      const target = resolveConversationThread(conversationId, page.threadId, tasks.data);
      if (!target)
        throw Error(
          "This conversation could not be matched to a current thread. Refresh the thread list.",
        );
      openAgentThread(scope.agentId, target.taskId, messageId);
    });
    if (settled._tag === "Failure" && getNavigationScope() === captured) {
      const cause = squashAtomCommandFailure(settled);
      setThreadError(cause instanceof Error ? cause.message : "Conversation lookup failed.");
    }
  };
  const moveHistory = (step: -1 | 1) => {
    const index = history.index + step;
    const entry = history.entries[index];
    if (!entry || entry.hostId !== hostId) return;
    openChat(entry.kind, entry.id, false);
    setHistory({ ...history, index });
  };
  const navigationKey = JSON.stringify(navigation);
  const applyNavigation = useStableCallback(
    (
      enabled: boolean,
      currentHost: string | null,
      key: string,
      agentList: typeof agents.data,
      channelData: typeof channels.data,
    ) => {
      if (!enabled || !currentHost || handledNavigation.current === key) return;
      if (navigation.botHost && navigation.botHost !== currentHost) return;
      if (navigation.botAgent && !agentList?.some((agent) => agent.id === navigation.botAgent))
        return;
      if (
        navigation.botChannel &&
        !channelList(channelData)?.some((channel) => channel.id === navigation.botChannel)
      )
        return;
      handledNavigation.current = key;
      if (navigation.botCreate === "group") {
        setGroupCreation(navigation.botVisit ?? key);
        setSelectedChannel(null);
        setSection("groups");
      } else if (navigation.botAgent && navigation.botMessage)
        openAgentThread(navigation.botAgent, navigation.botTask ?? null, navigation.botMessage);
      else if (navigation.botAgent) {
        openChat("bot", navigation.botAgent);
        if (navigation.botRoutine) {
          setRoutineTarget({ agentId: navigation.botAgent, id: navigation.botRoutine });
          setView("Routines");
        }
      } else if (navigation.botChannel) openChat("group", navigation.botChannel);
      else if (navigation.botPage === "search") setSearchOpen(true);
      else if (navigation.botPage === "chats") {
        const entry = history.entries[history.index];
        if (entry?.hostId === currentHost) openChat(entry.kind, entry.id, false);
        else setSection("chats");
      } else if (navigation.botPage) setSection(navigation.botPage);
    },
  );
  // oxlint-disable-next-line t3code/no-unreasoned-state-sync -- Consume an explicit navigation after the owning host/roster becomes available; background retained views never navigate.
  useEffect(() => {
    applyNavigation(active, hostId, navigationKey, agents.data, channels.data);
  }, [active, hostId, navigationKey, agents.data, channels.data, applyNavigation]);
  return (
    <SourceProviderHost environmentId={environmentId} hostId={hostId}>
      <BotWorkspaceChrome
        label={label}
        environmentId={environmentId}
        hostId={hostId}
        section={section}
        view={view}
        canBack={history.index > 0 && history.entries[history.index - 1]?.hostId === hostId}
        canForward={
          history.index + 1 < history.entries.length &&
          history.entries[history.index + 1]?.hostId === hostId
        }
        onBack={() => moveHistory(-1)}
        onForward={() => moveHistory(1)}
        bot={bot}
        sidePanelMaximized={section === "chats" && view !== "Tasks" && maximized && panelVisible}
        sidePanelHeader={
          section === "chats" &&
          scope &&
          panelVisible &&
          view !== "Tasks" &&
          (view !== "Chat" || selectedSideThread) ? (
            <SourceSidePanelHeader
              openPanes={panes}
              selected={view === "Chat" ? null : view}
              onSelect={setView}
              onClose={(pane) => {
                setPanes(panes.filter((other) => other !== pane));
                if (view === pane) setView(panes.find((other) => other !== pane) ?? "Chat");
              }}
              onCollapse={() => setView("Chat")}
              maximized={maximized}
              onMaximize={() => setMaximized((old) => !old)}
              threads={{
                threads: (taskViews(tasks.data) ?? [])
                  .filter((task) => threadLayout.side.includes(task.id))
                  .sort(
                    (a, b) => threadLayout.side.indexOf(a.id) - threadLayout.side.indexOf(b.id),
                  ),
                selectedId: view === "Chat" ? selectedSideThread : null,
                onSelect: (id) => {
                  setSideThreadSelection({ scope: threadScope, id });
                  setView("Chat");
                  setPanelVisible(true);
                },
                onClose: (id) => setThreadLayout(closeThreadTab(threadLayout, id, "side")),
                onMove: (id, index) =>
                  setThreadLayout(moveThreadTab(threadLayout, id, index, "side")),
                onMoveToChat: (id) => {
                  setThreadLayout(dockThreadTab(threadLayout, id, "open"));
                  setSideThreadSelection(null);
                },
              }}
            />
          ) : undefined
        }

        onOpenSearch={() => openCommandPalette()}
        tasks={taskViews(tasks.data) ?? []}
        selectedTaskId={selectedTaskId}
        threadLayout={threadLayout}
        onThreadLayout={setThreadLayout}
        onMoveThreadToSide={moveThreadToSide}
        newThread={newThread}
        onTogglePanel={() => {
          if (view === "Tasks") {
            setView("Files");
            return;
          }
          if (panelVisible) setPanelVisible(false);
          else {
            setPanelVisible(true);
            if (view === "Chat" && !selectedSideThread) setView("Files");
          }
        }}
        onNewThread={() => {
          setDraftThreadScope(threadScope);
          setView("Chat");
        }}
        onTask={(id) => {
          selectThread(id);
          setView("Chat");
        }}
        onRenameTask={async (taskId, title) => {
          if (!hostId || !bot || renameLock.current) return false;
          renameLock.current = true;
          setThreadError(null);
          const result = await settlePromise(() =>
            renameThread({
              environmentId,
              input: {
                hostId,
                request: { operation: "thread.rename", agentId: bot.id, taskId, title },
              },
            }),
          );
          renameLock.current = false;
          if (result._tag === "Failure" || result.value._tag === "Failure") {
            setThreadError(
              "Thread rename was refused or its outcome is unknown. Refresh the thread list before trying again.",
            );
            return false;
          }
          tasks.refresh();
          return true;
        }}
        agents={agents.data ?? []}
        channels={(channelList(channels.data) ?? []).filter((item) => !item.archived)}
        people={{
          members: people.members,
          selfId: people.selfId,
          threads: people.threads,
          selected: section === "direct" ? (person?.id ?? null) : null,
          onSelect: (id) => openChat("person", id),
        }}
        selectedChannel={selectedChannel}
        loading={agents.isPending}
        onSection={setSection}
        onBot={(id) => (section === "flows" ? selectBot(id) : openChat("bot", id))}
        onGroup={(id) => openChat("group", id)}
        onView={setView}
        onRefresh={() => {
          host.refresh();
          agents.refresh();
          channels.refresh();
          people.refresh();
        }}
      >
        {threadError && (
          <p role="alert" className="p-3 text-sm text-destructive">
            {threadError}
          </p>
        )}
        {hostId && (host.error || agents.error) && (
          <div
            role="alert"
            className="flex flex-wrap items-center gap-3 border-b border-destructive/30 bg-destructive/5 px-5 py-3"
          >
            <p className="min-w-0 flex-1 text-pretty text-sm text-destructive">
              {host.error ?? agents.error}
            </p>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                host.refresh();
                agents.refresh();
              }}
            >
              <RefreshCwIcon aria-hidden className="size-3.5" />
              Try again
            </Button>
          </div>
        )}
        <Suspense fallback={<BotWorkspaceLoading />}>
          {!hostId ? (
            host.isPending ? (
              <BotWorkspaceLoading />
            ) : (
              <Empty size="compact">
                <EmptyHeader>
                  <EmptyMedia>
                    <ServerOffIcon aria-hidden className="size-7" />
                  </EmptyMedia>
                  <EmptyTitle>Bots are offline</EmptyTitle>
                  <EmptyDescription>
                    {host.error ??
                      host.data?.reason ??
                      "Connect to the computer that hosts your bots, or enable hosting on this computer."}
                  </EmptyDescription>
                </EmptyHeader>
                <EmptyContent>
                  <Button variant="outline" onClick={host.refresh}>
                    Try again
                  </Button>
                  <Button
                    variant="ghost-muted"
                    render={<Link to="/settings/bots" search={{ machine: environmentId }} />}
                  >
                    Hosting settings
                  </Button>
                </EmptyContent>
              </Empty>
            )
          ) : section === "direct" ? (
            person && people.selfId ? (
              <ReactBotDirectConversation
                key={JSON.stringify([environmentId, hostId, people.selfId, person.id])}
                environmentId={environmentId}
                hostId={hostId}
                member={person}
                selfId={people.selfId}
                onChanged={people.refresh}
              />
            ) : (
              <p role="status" className="p-4">
                {people.error ?? "This person is no longer available on this host."}
              </p>
            )
          ) : section === "groups" ? (
            <ReactBotGroups
              key={selectedChannel ?? groupCreation ?? "groups"}
              environmentId={environmentId}
              hostId={hostId}
              initialCreate={!selectedChannel && groupCreation !== null}
              onSelectAgent={(id) => openChat("bot", id)}
              {...(selectedChannel ? { initialChannelId: selectedChannel, embedded: true } : {})}
            />
          ) : section === "usage" ? (
            <ReactBotUsage environmentId={environmentId} hostId={hostId} hostName={label} />
          ) : section === "tasks" ? (
            <TasksPage
              environmentId={environmentId}
              hostId={hostId}
              hostName={label}
              agents={agents.data ?? []}
              onBack={() => setSection("chats")}
            />
          ) : section === "chats" && scope ? (
            <BotFileSelectionWorkspace key={`${threadScope}:${selectedTaskId ?? "main"}`}>
              <div className="ob-workspace-conversation">
                <div
                  className={cn(
                    "ob-conversation-main",
                    (view === "Tasks" ||
                      (maximized && panelVisible && (view !== "Chat" || selectedSideThread))) &&
                      "hidden",
                  )}
                  inert={view === "Tasks"}
                >
                  {newThread ? (
                    <SourceNewThreadDraft
                      {...scope}
                      initialDraft={drafts[`${threadScope}:new`] ?? ""}
                      onDraftChange={(text) =>
                        setDrafts((current) => ({ ...current, [`${threadScope}:new`]: text }))
                      }
                      onCreated={(id) => {
                        selectThread(id);
                        setDrafts((current) => {
                          const next = { ...current };
                          delete next[`${threadScope}:new`];
                          return next;
                        });
                        tasks.refresh();
                      }}
                      onCancel={() => setDraftThreadScope(null)}
                    />
                  ) : (
                    <BotConversationPanel
                      key={`${hostId}:${bot!.id}:${selectedTaskId ?? "main"}`}
                      {...scope}
                      taskId={selectedTaskId}
                      publishFileSelection
                      agentName={bot!.name}
                      agent={bot!}
                      composerAccessory={
                        <SourceModelPicker
                          key={`${hostId}:${bot!.id}`}
                          environmentId={environmentId}
                          hostId={hostId!}
                          agentId={bot!.id}
                          onManage={openProviders}
                        />
                      }
                      {...(focusMessageId ? { focusMessageId } : {})}
                      workspace
                      initialDraft={drafts[draftKey] ?? ""}
                      onDraftChange={(text) =>
                        setDrafts((current) =>
                          current[draftKey] === text ? current : { ...current, [draftKey]: text },
                        )
                      }
                      onOpenFiles={() => setView("Files")}
                      onOpenQuotedFile={(preview) => {
                        setQuotedFile({ key: draftKey, preview });
                        setView("Files");
                      }}
                    />
                  )}
                </div>
                {panelVisible && selectedSideThread && view === "Chat" && (
                  <aside className="conversation-panel ob-tools-pane">
                    <BotConversationPanel
                      key={`side:${threadScope}:${selectedSideThread}`}
                      {...scope}
                      taskId={selectedSideThread}
                      agent={bot!}
                      onOpenQuotedFile={(preview) => {
                        selectThread(selectedSideThread);
                        setQuotedFile({
                          key: `${hostId}:${bot?.id}:${selectedSideThread}`,
                          preview,
                        });
                        setView("Files");
                      }}
                      workspace
                    />
                  </aside>
                )}
                {panelVisible && view !== "Chat" && (
                  <div
                    className={view === "Tasks" ? "flex min-h-0 flex-1 flex-col" : "ob-tools-pane"}
                  >
                    {view === "Tasks" && (
                      <BotDetail
                        key={`tasks:${bot!.id}`}
                        {...scope}
                        expectedHostId={hostId}
                        workspaceView="task"
                      />
                    )}
                    {view !== "Tasks" && (
                      <>
                        <div
                          className={cn(
                            "ob-tools-scroll ob-source-tool",
                            view === "Settings" && "side-panel-docked",
                          )}
                        >
                          {view === "Memory" && (
                            <MemoryEnvironment
                              {...scope}
                              agentName={bot!.name}
                              onBack={() => setView("Settings")}
                              onClose={() => setView("Chat")}
                            />
                          )}
                          {view === "Routines" && (
                            <AgentRoutinesSettings
                              key={`${threadScope}:${routineTarget?.agentId === bot!.id ? routineTarget.id : "list"}`}
                              {...scope}
                              {...(routineTarget?.agentId === bot!.id
                                ? { initialRoutineId: routineTarget.id }
                                : {})}
                              onBack={() => setView("Settings")}
                              onClose={() => setView("Chat")}
                            />
                          )}
                          {view === "Files" &&
                            (quotedFile?.key === draftKey ? (
                              <BotFilePreview
                                name={quotedFile.preview.file.name}
                                mimeType={quotedFile.preview.file.mimeType}
                                sizeBytes={quotedFile.preview.file.size}
                                asset={{
                                  environmentId,
                                  attachmentId: quotedFile.preview.file.attachmentId,
                                }}
                                quoteTarget={quotedFile.preview.target}
                                revealText={quotedFile.preview.text}
                                onClose={() => setQuotedFile(null)}
                              />
                            ) : (
                              <FilesEnvironment
                                {...scope}
                                agentName={bot!.name}
                                onBack={() => setView("Settings")}
                                onClose={() => setView("Chat")}
                                onOpenConversation={(conversationId) => {
                                  void openFileConversation(conversationId);
                                }}
                                onShowMessage={(file) => {
                                  if (file.conversation && file.messageId)
                                    void openFileConversation(file.conversation.id, file.messageId);
                                }}
                              />
                            ))}
                          {view === "Browser" && active && (
                            <SourceBrowserEnvironment {...scope} onClose={() => setView("Chat")} />
                          )}
                          {view === "Computer" && active && (
                            <ComputerEnvironment
                              environmentId={environmentId}
                              hostId={hostId}
                              workspace
                            />
                          )}
                          {view === "Vault" && (
                            <BotVault environmentId={environmentId} hostId={hostId} />
                          )}
                          {view === "Data" && (
                            <DataEnvironment
                              environmentId={environmentId}
                              hostId={hostId}
                              workspace
                            />
                          )}
                          {view === "Settings" && (
                            <SourceAgentSettings
                              environmentId={environmentId}
                              hostId={hostId}
                              agent={bot!}
                              onClose={() => setView("Chat")}
                              onManageProviders={openProviders}
                              onOpenMemory={() => setView("Memory")}
                              onOpenRoutines={() => setView("Routines")}
                              onOpenSharedTables={() => setView("Data")}
                              onOpenFiles={() => setView("Files")}
                            />
                          )}
                        </div>
                      </>
                    )}
                  </div>
                )}
              </div>
            </BotFileSelectionWorkspace>
          ) : section === "chats" ? (
            <Empty size="compact">
              <EmptyHeader>
                <EmptyMedia>
                  <BotIcon aria-hidden className="size-7" />
                </EmptyMedia>
                <EmptyTitle>Your bots, together</EmptyTitle>
                <EmptyDescription>
                  Choose a bot to open its conversation, or create one to get started.
                </EmptyDescription>
              </EmptyHeader>
              <EmptyContent>
                <Button variant="outline" onClick={() => setSection("manage")}>
                  Create bot
                </Button>
              </EmptyContent>
            </Empty>
          ) : (
            <div
              className={cn(
                "min-h-0 flex-1",
                [
                  "host-settings",
                  "marketplace",
                  "workflows",
                  "flows",
                  "schedule",
                  "manage",
                ].includes(section)
                  ? "flex flex-col"
                  : section === "attention"
                    ? "overflow-auto"
                    : "space-y-5 overflow-auto p-5",
              )}
            >
              {section === "manage" && (
                <SourceCreateAgent
                  environmentId={environmentId}
                  hostId={hostId}
                  first={!agents.data?.length}
                  onCancel={() => setSection("chats")}
                  onCreated={(id) => {
                    agents.refresh();
                    agentDetails.refresh();
                    openChat("bot", id);
                  }}
                  onManageProviders={openProviders}
                />
              )}
              {section === "attention" && (
                <BotAttention
                  environmentId={environmentId}
                  conversationForRequest={(request) => {
                    const channel = channelList(channels.data)?.find(
                      (item) =>
                        !item.archived &&
                        item.threads?.some(
                          (thread) =>
                            thread.agentId === request.agentId &&
                            thread.threadId === request.threadId,
                        ),
                    );
                    return channel
                      ? {
                          label: channel.name,
                          onOpen: () => {
                            setSelectedChannel(channel.id);
                            setSection("groups");
                          },
                        }
                      : null;
                  }}
                />
              )}
              {section === "marketplace" && (
                <SourceMarketplace
                  environmentId={environmentId}
                  hostId={hostId}
                  agents={agents.data ?? []}
                  activeAgentId={bot?.id}
                  onCompose={(agentId, text) => {
                    if (!hostId || !agents.data?.some((agent) => agent.id === agentId))
                      return false;
                    const key = `${hostId}:${agentId}:main`;
                    setDrafts((current) => ({
                      ...current,
                      [key]: current[key] ? `${current[key]}\n${text}` : text,
                    }));
                    openAgentThread(agentId, null);
                    return true;
                  }}
                  onOpenAgent={(id) => openChat("bot", id)}
                  onSignIn={() => {
                    void navigate({
                      to: "/settings/bots",
                      search: { machine: environmentId },
                      hash: "bot-host-account",
                    });
                  }}
                />
              )}
              {section === "workflows" && (
                <WorkflowsPage environmentId={environmentId} hostId={hostId} />
              )}
              {section === "schedule" && (
                <SchedulePage
                  environmentId={environmentId}
                  hostId={hostId}
                  hostName={label}
                  agents={agents.data ?? []}
                  onOpenAgent={(id) => openChat("bot", id)}
                  onCreateRoutine={(agentId) => {
                    openChat("bot", agentId);
                    setRoutineTarget({ agentId, id: null });
                    setView("Routines");
                  }}
                  onOpenRoutine={(routine) => {
                    if (routine.owner.kind === "agent") {
                      openChat("bot", routine.owner.agentId);
                      setRoutineTarget({ agentId: routine.owner.agentId, id: routine.id });
                      setView("Routines");
                    } else openChat("group", routine.owner.channelId);
                  }}
                  onBack={() => setSection("chats")}
                />
              )}
              {section === "flows" && (
                <>
                  <BotRoutineFlows
                    environmentId={environmentId}
                    hostId={hostId}
                    workspace
                    onCreateRoutine={(agentId) => {
                      openChat("bot", agentId);
                      setRoutineTarget({ agentId, id: null });
                      setView("Routines");
                    }}
                    onEditRoutine={(agentId, id) => {
                      openChat("bot", agentId);
                      setRoutineTarget({ agentId, id });
                      setView("Routines");
                    }}
                    {...(bot ? { agentId: bot.id } : {})}
                  />
                </>
              )}
            </div>
          )}
        </Suspense>
      </BotWorkspaceChrome>
      {hostId && (
        <SourceGlobalSearch
          key={`${environmentId}:${hostId}`}
          environmentId={environmentId}
          hostId={hostId}
          open={searchOpen}
          onOpenChange={setSearchOpen}
          agents={agents.data ?? []}
          channels={channelList(channels.data) ?? []}
          actions={[
            {
              id: "new-agent",
              label: "New agent",
              group: "actions",
              run: () => setSection("manage"),
            },
            {
              id: "marketplace",
              label: "Marketplace",
              group: "actions",
              run: () => setSection("marketplace"),
            },
            {
              id: "schedule",
              label: "Schedule",
              group: "actions",
              run: () => setSection("schedule"),
            },
            {
              id: "app-settings",
              label: "App settings",
              group: "settings",
              run: () => setSection("settings"),
            },
            {
              id: "host-settings",
              label: "Server settings",
              group: "settings",
              run: () => setSection("host-settings"),
            },
          ]}
          onSelect={(target) => {
            if (target.kind === "agent") openChat("bot", target.id);
            else if (target.kind === "channel") openChat("group", target.id);
            else if (target.kind === "message") {
              openAgentThread(target.agentId, target.taskId ?? null, target.messageId);
            } else if (target.routine.agentId) {
              openChat("bot", target.routine.agentId);
              setRoutineTarget({ agentId: target.routine.agentId, id: target.routine.id });
              setView("Routines");
            } else if (target.routine.channelId) openChat("group", target.routine.channelId);
          }}
        />
      )}
    </SourceProviderHost>
  );
}

function BotWorkspaceLoading() {
  return (
    <div
      role="status"
      aria-label="Loading bot workspace"
      className="mx-auto flex w-full max-w-4xl flex-col gap-6 p-6"
    >
      <span className="sr-only">Loading bot workspace…</span>
      <Skeleton className="h-5 w-40" />
      <div className="flex items-start gap-3">
        <Skeleton className="size-8 shrink-0" shape="pill" />
        <div className="flex flex-1 flex-col gap-3">
          <Skeleton className="h-4 w-36" />
          <Skeleton className="h-20 w-2/3" shape="card" />
        </div>
      </div>
    </div>
  );
}
